function safeGetValue(accId, serviceId, charId, context, fallback = null) {
    try {
        const acc = Hub.getAccessory(accId);
        if (!acc) {
            throw new Error("accessory=null");
        }

        const service = acc.getService(serviceId);
        if (!service) {
            throw new Error("service " + serviceId + "=null");
        }

        const ch = service.getCharacteristic(charId);
        if (!ch) {
            throw new Error("char " + charId + "=null");
        }

        return ch.value;
    } catch (e) {
        log.error(
            "⛔ safeGetValue | " + context +
            " | acc=" + accId +
            ", svc=" + serviceId +
            ", char=" + charId +
            " → " + e.message
        );
        return fallback;
    }
}

function sendTG(message) {
    try {
        const safeMessage = String(message).replace(/_/g, '\\_');
        Notify
            .text(safeMessage)
            .to("telegram_1")
            .send();
    } catch (e) {
        log.error("⛔ Ошибка отправки Telegram: " + e.message);
    }
}

function getWeatherValue(accId, svcId, chId, context, yrField, defaultVal) {
    var real = safeGetValue(accId, svcId, chId, context, null);
    if (real !== null && real !== undefined && !(typeof real === "number" && isNaN(real))) {
        return real;
    }
    if (global.yr && global.yr[yrField] != null) {
        return global.yr[yrField];
    }
    return (global.lastExternalData && global.lastExternalData[yrField] != null)
        ? global.lastExternalData[yrField]
        : defaultVal;
}

var presenceSensors = [
    { accId: 535, svcId: 17, chId: 19, name: "Олеся",   emoji: "👱🏼‍♀️" },
    { accId: 535, svcId: 13, chId: 15, name: "Андрей",  emoji: "🧔🏻‍♂️" },
    { accId: 535, svcId: 21, chId: 23, name: "Кристина", emoji: "👧" }
];

function getPresenceEmojis() {
    var result = "";
    presenceSensors.forEach(function(p) {
        var val = safeGetValue(p.accId, p.svcId, p.chId, "Присутствие " + p.name, 0);
        if (val === 1) {
            result += p.emoji;
        }
    });
    return result;
}

if (!global.lastRoomTemps) global.lastRoomTemps = {};
if (!global.lastExternalData) global.lastExternalData = { temp: 0, temp_min_6_hours: 0, wind: 0, uv: 0, cloud: 0 };
if (global.lastExternalData.uv === undefined) global.lastExternalData.uv = 0;
if (global.lastExternalData.cloud === undefined) global.lastExternalData.cloud = 0;
if (!global.stableColdRoomCount) global.stableColdRoomCount = 0;
if (!global.stableHotRoomCount) global.stableHotRoomCount = 0;
if (!global.lastColdestRoom) global.lastColdestRoom = "";
if (!global.ignoredRooms) global.ignoredRooms = {};
if (!global.ventilationStatus) global.ventilationStatus = {};
if (!global.windowStatus) global.windowStatus = {};
if (!global.floorHeatingState) global.floorHeatingState = {};
if (!global.heatingIntegral) global.heatingIntegral = 0;
if (!global.lastPiUpdateTime) global.lastPiUpdateTime = Date.now();

var ignoreTemperature = {};

// Единый конфиг по комнатам: все ID аксессуаров/сервисов/характеристик в одном месте.
// Формат [accId, svcId, chId] — тройка ID для safeGetValue().
// Чтобы добавить/изменить комнату — меняем только здесь, остальные функции ничего не знают
// про конкретные ID и просто читают их из этого объекта.
var ROOM_CONFIG = {
    "Спальня": {
        targetTemp: [488, 13, 18],               // термостат: целевая температура комнаты
        sensor: [428, 13, 15],                   // датчик: текущая температура комнаты
        windows: [[370, 13, 15]],                // массив окон (может быть несколько) — открыто/закрыто
        ventilation: [268, 13, 15],              // датчик вентиляции; null = вентиляции в комнате нет
        floorHeating: [479, 22, 24],             // контур тёплого пола (вкл/выкл)
        radiators: [[303, 13, 15]],              // массив радиаторов (может быть несколько) — греет/не греет
        airQuality: { acc: 249, svc: 27, ch: 30, type: "CO₂", unit: "ppm" } // датчик качества воздуха; null = нет датчика
    },
    "Детская": {
        targetTemp: [487, 13, 18],
        sensor: [512, 13, 15],
        windows: [[371, 13, 15], [389, 13, 15]], // два окна в комнате
        ventilation: null,                       // вентиляции нет
        floorHeating: [479, 13, 15],
        radiators: [[308, 13, 15], [309, 13, 15]], // два радиатора
        airQuality: { acc: 572, svc: 35, ch: 38, type: "CO₂", unit: "ppm" } // CO₂ датчик в Детской
    },
    "Гост-ая": {
        targetTemp: [480, 13, 18],
        sensor: [302, 13, 15],
        windows: [[385, 13, 15], [386, 13, 15]],
        ventilation: [410, 13, 15],
        floorHeating: [479, 16, 18],
        radiators: [[307, 13, 15], [304, 13, 15]],
        airQuality: { acc: 509, svc: 27, ch: 30, type: "CO₂", unit: "ppm" }
    },
    "Кухня 🍽️": {
        targetTemp: [486, 13, 18],
        sensor: [483, 13, 15],
        windows: [[388, 13, 15], [387, 13, 15]],
        ventilation: null,
        floorHeating: [479, 19, 21],
        radiators: [[296, 13, 15]],
        airQuality: { acc: 483, svc: 19, ch: 22, type: "TVOC", unit: "ppb" } // тут не CO₂, а TVOC
    }
};

// Открыто ли хотя бы одно окно в комнате (по всем окнам из cfg.windows)
function isWindowOpen(room) {
    var cfg = ROOM_CONFIG[room];
    if (!cfg) { log.error(`Комната ${room} не найдена в конфиге`); return false; }
    return cfg.windows.some(w => safeGetValue(w[0], w[1], w[2], "Окно " + room, 0) === 1);
}

// Включена ли вентиляция в комнате (false, если в комнате её нет вообще — cfg.ventilation === null)
function isVentilationOn(room) {
    var cfg = ROOM_CONFIG[room];
    if (!cfg || !cfg.ventilation) return false;
    return safeGetValue(cfg.ventilation[0], cfg.ventilation[1], cfg.ventilation[2], "Вентиляция " + room, 0) === 1;
}

// Включён ли тёплый пол в комнате; попутно сохраняет состояние в global.floorHeatingState[room]
// (используется для дальнейшей диагностики/истории, не только для текущего сообщения)
function isFloorHeatingOn(room) {
    var cfg = ROOM_CONFIG[room];
    if (!cfg || !cfg.floorHeating) return false;
    var raw = safeGetValue(cfg.floorHeating[0], cfg.floorHeating[1], cfg.floorHeating[2], "ТП " + room, 0);
    var isOn = (raw === 1 || raw === true || raw === "1");
    global.floorHeatingState[room] = isOn;
    return isOn;
}

// Греет ли хотя бы один радиатор в комнате (по всем радиаторам из cfg.radiators)
function isRadiatorOn(room) {
    var cfg = ROOM_CONFIG[room];
    if (!cfg) { log.error(`Комната ${room} не найдена в конфиге`); return false; }
    return cfg.radiators.some(r => safeGetValue(r[0], r[1], r[2], "Радиатор " + room, 0) === 1);
}

// Данные качества воздуха для комнаты (CO₂ или TVOC — зависит от датчика);
// возвращает null, если в комнате такого датчика нет (cfg.airQuality === null)
function getAirQualityData(room) {
    var cfg = ROOM_CONFIG[room];
    if (!cfg || !cfg.airQuality) return null;
    var aq = cfg.airQuality;
    return {
        value: safeGetValue(aq.acc, aq.svc, aq.ch, aq.type + " " + room, null),
        unit: aq.unit,
        type: aq.type
    };
}

// Функция для проверки состояния котла
function isBoilerOn() {
    const raw = safeGetValue(275, 13, 15, "Котёл Active", 0);
    const isOn = (raw === 1 || raw === true || raw === "1");
    global.boilerState = isOn;
    return isOn;
}

// Функция для проверки состояния насоса тёплого пола
function isFloorPumpOn() {
    const raw = safeGetValue(114, 13, 15, "Насос ТП", 0);
    const isOn = (raw === 1 || raw === true || raw === "1");
    global.floorPumpState = isOn;
    return isOn;
}

// Обновляем функцию updateIgnoredRooms
function updateIgnoredRooms(rooms) {
    if (!rooms) {
        log.error("Ошибка: rooms не определено в updateIgnoredRooms.");
        return;
    }

    Object.keys(rooms).forEach(room => {
        let ventilationOn = isVentilationOn(room);
        let windowOpen = isWindowOpen(room);

        log.info(`Комната: ${room}, Окно открыто: ${windowOpen}, Вентиляция включена: ${ventilationOn}`);

        if (windowOpen || ventilationOn) {
            ignoreTemperature[room] = true;
            log.info(`Температура в комнате ${room} будет игнорироваться.`);
        } else {
            ignoreTemperature[room] = false;
            log.info(`Температура в комнате ${room} будет учитываться.`);
        }
    });
}

// Функция для нахождения самой холодной комнаты с учётом только отрицательных отклонений
function getColdestRoom(rooms) {
    if (!rooms) {
        log.error("Ошибка: rooms не определено в getColdestRoom.");
        return null;
    }

    let sortedRooms = Object.keys(rooms)
        .filter(room => !ignoreTemperature[room]) // Игнорируем комнаты с открытыми окнами/вентиляцией
        .filter(room => rooms[room].sensor < rooms[room].target) // Оставляем только те комнаты, где температура ниже целевой
        .sort((a, b) => (rooms[b].target - rooms[b].sensor) - (rooms[a].target - rooms[a].sensor)); // Сортируем по разнице между целевой и текущей температурой

    if (sortedRooms.length === 0) {
        log.info("Нет комнат ниже целевой температуры (все либо прогреты, либо игнорируются из-за окон/вентиляции). Выбираем наименее перегретую, теплоноситель сбросится на базовую.");
        sortedRooms = Object.keys(rooms)
            .filter(room => !ignoreTemperature[room])
            .sort((a, b) => (rooms[b].target - rooms[b].sensor) - (rooms[a].target - rooms[a].sensor));
    }

    return sortedRooms.length ? sortedRooms[0] : null;
}

global.adjust_heating = function() {
    try {
        if (typeof Hub === 'undefined' || Hub == null) {
            if (typeof log !== 'undefined' && log && log.error) {
                log.error("⛔ Hub недоступен. Функция запущена вне контекста SprutHub.");
            } else {
                print("⛔ Hub недоступен. Функция запущена вне контекста SprutHub.");
            }

            if (global && typeof global.sendToTelegram === 'function') {
                sendTG("⚠️ Ошибка: Hub недоступен. Используй runGlobal('Регулировка температуры комфорта OpenTherm. Глобальный')");
            }

            return;
        }

        // ---- Погода: приоритет реальным датчикам метеостанции WS90, fallback на global.yr (Yr.no) ----
        var outsideTemp = getWeatherValue(537, 13, 15, "Температура WS90", "temp", 0);
        var uvIndex = getWeatherValue(537, 25, 27, "УФ WS90", "uv", 0);
        var windSpeed = getWeatherValue(537, 40, 42, "Скорость ветра WS90", "wind", 0);

        var forecastTemp = (global.yr && global.yr.temp_min_6_hours != null) ? global.yr.temp_min_6_hours : global.lastExternalData.temp_min_6_hours;
        var cloudiness = (global.yr && global.yr.cloud != null) ? global.yr.cloud : global.lastExternalData.cloud;

        var weatherCondition = safeGetValue(537, 61, 63, "Погода WS90", null);
        if (!weatherCondition) {
            weatherCondition = (global.yr && global.yr.condition_1_hour) ? global.yr.condition_1_hour : "Нет данных";
        }

        global.lastExternalData = {
            temp: outsideTemp,
            temp_min_6_hours: forecastTemp,
            wind: windSpeed,
            uv: uvIndex,
            cloud: cloudiness
        };

        // ---- Расчёт базовой (отопительной кривой) температуры теплоносителя ----
        // Базовая температура (53) при 0°C на улице и целевой в помещении 25°C
        var baseWaterTemp = 53 + (0 - outsideTemp) * 1;
        var tempDifference = forecastTemp - outsideTemp;
        var forecastCorrection = tempDifference / 2;
        baseWaterTemp += forecastCorrection;

        var windCorrection = 0;
        if (windSpeed >= 3 && windSpeed < 6) windCorrection = 1;
        else if (windSpeed >= 6 && windSpeed < 9) windCorrection = 2;
        else if (windSpeed >= 10) windCorrection = 3;
        baseWaterTemp += windCorrection;

        // Определение облачности (эмодзи для сообщения)
        var cloudEmoji = "☀️";
        if (cloudiness >= 30 && cloudiness < 50) cloudEmoji = "🌤";
        else if (cloudiness >= 50 && cloudiness < 80) cloudEmoji = "⛅";
        else if (cloudiness >= 80) cloudEmoji = "☁️";

        // Коррекция по УФ и облачности (солнечный прогрев снижает требуемую температуру теплоносителя)
        var uvCorrection = 0;
        if (uvIndex >= 0.8 && uvIndex < 1.5) {
            if (cloudiness < 30) uvCorrection = -3;
            else if (cloudiness < 50) uvCorrection = -2;
            else if (cloudiness < 80) uvCorrection = -1;
        } else if (uvIndex >= 1.5 && uvIndex <= 2.5) {
            if (cloudiness < 30) uvCorrection = -4;
            else if (cloudiness < 50) uvCorrection = -3;
            else if (cloudiness < 80) uvCorrection = -2;
        } else if (uvIndex > 2.5) {
            if (cloudiness < 30) uvCorrection = -5;
            else if (cloudiness < 50) uvCorrection = -4;
            else if (cloudiness < 80) uvCorrection = -3;
        }
        baseWaterTemp += uvCorrection;

        if (baseWaterTemp < 40) baseWaterTemp = 40;
        if (baseWaterTemp > 80) baseWaterTemp = 80;

        // ---- Данные по комнатам (целевая/текущая температура) ----
        var targetTemps = {};
        var rooms = {};
        Object.keys(ROOM_CONFIG).forEach(function(room) {
            var cfg = ROOM_CONFIG[room];
            var target = safeGetValue(cfg.targetTemp[0], cfg.targetTemp[1], cfg.targetTemp[2], "Целевая температура " + room, 24);
            targetTemps[room] = target;
            rooms[room] = {
                target: target,
                sensor: safeGetValue(cfg.sensor[0], cfg.sensor[1], cfg.sensor[2], "Температура " + room, null)
            };
        });

        // Если датчик температуры недоступен — используем последнее известное значение
        for (var room in rooms) {
            if (rooms[room].sensor == null || isNaN(rooms[room].sensor)) {
                log.warn(`Датчик в комнате ${room} недоступен. Используем последнее известное значение.`);
                rooms[room].sensor = global.lastRoomTemps[room] || rooms[room].target;
            } else {
                global.lastRoomTemps[room] = rooms[room].sensor;
            }
        }

        for (var room in rooms) {
            log.info(`Комната: ${room}, Цель: ${rooms[room].target}, Сейчас: ${rooms[room].sensor}, Δ=${(rooms[room].target - rooms[room].sensor).toFixed(2)}`);
        }

        updateIgnoredRooms(rooms);
        var coldestRoom = getColdestRoom(rooms);

        if (!coldestRoom) {
            log.error("Не удалось определить самую холодную комнату.");
            global.sendToTelegram("⚠️ Ошибка: Не удалось определить самую холодную комнату. Все комнаты имеют открытые окна или вентиляцию. Температура теплоносителя сброшена на базовую.");
            return;
        }

        var minDelta = rooms[coldestRoom].target - rooms[coldestRoom].sensor;
        minDelta = Math.round(minDelta * 10) / 10;
        var rawMinDelta = minDelta; // "сырая" ошибка до ступенчатой эскалации — нужна для честного ПИ-теста
        var currentWaterTemp = safeGetValue(
            275, 13, 18,
            "Текущая температура теплоносителя",
            global.lastWaterTemp || 50
        );

        global.lastWaterTemp = currentWaterTemp;

        // ---- Эскалация для стабильно холодной/горячей комнаты ----
        // При смене самой холодной комнаты — отсчёт заново (шаг 1, текущее измерение не теряется).
        // Пока комната та же — шаг 2 (сохраняем прежнюю скорость эскалации).
        var sameColdestRoom = (coldestRoom === global.lastColdestRoom);
        var stepSize = sameColdestRoom ? 2 : 1;
        var coldBase = sameColdestRoom ? global.stableColdRoomCount : 0;
        var hotBase  = sameColdestRoom ? global.stableHotRoomCount  : 0;

        if (minDelta > 0.2) {
            global.stableColdRoomCount = coldBase + stepSize;
            global.stableHotRoomCount = 0;
        } else if (minDelta <= -0.2) {
            global.stableHotRoomCount = hotBase + stepSize;
            global.stableColdRoomCount = 0;
        } else {
            global.stableColdRoomCount = 0;
            global.stableHotRoomCount = 0;
        }

        // Многоступенчатая корректировка для стабильно холодной комнаты
        if (global.stableColdRoomCount >= 5) {
            minDelta += 2;
            log.info("🔼 Температура в самой холодной комнате стабильно низкая 5 раз. Повышаем Δ на 2°C.");
        } else if (global.stableColdRoomCount >= 4) {
            minDelta += 1.5;
            log.info("🔼 Температура в самой холодной комнате стабильно низкая 4 раза. Повышаем Δ на 1.5°C.");
        } else if (global.stableColdRoomCount >= 3) {
            minDelta += 1;
            log.info("🔼 Температура в самой холодной комнате стабильно низкая 3 раза. Повышаем Δ на 1°C.");
        }

        // Многоступенчатая корректировка для стабильного перегрева
        if (global.stableHotRoomCount >= 5) {
            minDelta -= 2;
            log.info("🔽 Температура в самой холодной комнате стабильно высокая 5 раз. Понижаем Δ на 2°C.");
        } else if (global.stableHotRoomCount >= 4) {
            minDelta -= 1.5;
            log.info("🔽 Температура в самой холодной комнате стабильно высокая 4 раза. Понижаем Δ на 1.5°C.");
        } else if (global.stableHotRoomCount >= 3) {
            minDelta -= 1;
            log.info("🔽 Температура в самой холодной комнате стабильно высокая 3 раза. Понижаем Δ на 1°C.");
        }

        global.lastColdestRoom = coldestRoom;

        // ---- ПИ-регулятор (теневой тест, пока НЕ управляет котлом — только логируется и шлётся в ТГ) ----
        var nowTs = Date.now();
        var dtHours = (nowTs - global.lastPiUpdateTime) / 3600000;
        dtHours = Math.min(dtHours, 1); // защита от огромного dt после простоя/перезагрузки
        global.lastPiUpdateTime = nowTs;

        var Ki = 1.5;            // подбирается по накопленным логам/сообщениям в ТГ
        var INTEGRAL_LIMIT = 3;  // °C·ч, антивиндап

        if (rawMinDelta >= -0.2 && rawMinDelta <= 0.2) {
            global.heatingIntegral = 0; // в мёртвой зоне — сброс
        } else {
            global.heatingIntegral += rawMinDelta * dtHours;
        }
        global.heatingIntegral = Math.max(-INTEGRAL_LIMIT, Math.min(INTEGRAL_LIMIT, global.heatingIntegral));

        var correctionFactorPI = 2;
        if (Math.abs(rawMinDelta) > 2) correctionFactorPI = 3;
        else if (Math.abs(rawMinDelta) > 1) correctionFactorPI = 2.5;

        var piCorrection = correctionFactorPI * rawMinDelta + Ki * global.heatingIntegral;
        var newWaterTemp_PI = Math.round(baseWaterTemp + piCorrection);
        if (newWaterTemp_PI < 40) newWaterTemp_PI = 40;
        if (newWaterTemp_PI > 80) newWaterTemp_PI = 80;

        // ---- Боевой расчёт температуры теплоносителя (ступенчатая логика) ----
        var correctionFactor = 2;
        if (Math.abs(minDelta) > 2) correctionFactor = 3;
        else if (Math.abs(minDelta) > 1) correctionFactor = 2.5;

        var newWaterTemp = baseWaterTemp + (minDelta * correctionFactor);
        newWaterTemp = Math.round(newWaterTemp);

        // Если самая холодная комната перегрета (Δ < 0), не повышаем температуру теплоносителя
        if (minDelta < 0) {
            if (newWaterTemp > currentWaterTemp) {
                newWaterTemp = currentWaterTemp;
                log.info("🔽 Самая холодная комната перегрета. Температура теплоносителя не повышается.");
            }
        }

        // Сброс на базовую температуру, если ближайшая к цели комната в "мёртвой зоне"
        if (minDelta >= -0.2 && minDelta <= 0.2) {
            newWaterTemp = baseWaterTemp;
            log.info("🔄 Температура в самой холодной комнате близка к целевой. Сбрасываем температуру теплоносителя на базовую.");
        }

        newWaterTemp = Math.round(newWaterTemp);

        // Защита: при стабильно высокой температуре теплоноситель не должен расти
        if (newWaterTemp > currentWaterTemp && global.stableHotRoomCount >= 3) {
            log.warn("🔽 Коррекция отменена: стабильно высокая температура, но теплоноситель почему-то растёт. Проверяем расчёты.");
            newWaterTemp = currentWaterTemp - 1;
        }

        // Защита: при стабильно низкой температуре теплоноситель не должен падать
        if (newWaterTemp < currentWaterTemp && global.stableColdRoomCount >= 3) {
            log.warn("🔼 Коррекция отменена: стабильно низкая температура, но теплоноситель почему-то не растёт. Принудительно увеличиваем.");
            newWaterTemp = currentWaterTemp + 1;
        }

        if (newWaterTemp < 40) newWaterTemp = 40;
        if (newWaterTemp > 80) newWaterTemp = 80;

        log.info(`DEBUG: currentWaterTemp=${currentWaterTemp}, newWaterTemp=${newWaterTemp}, minDelta=${minDelta}`);
        log.info(`Коррекция отопления: Самая холодная комната: ${coldestRoom}, Δ=${minDelta.toFixed(1)}, Текущий теплоноситель=${currentWaterTemp.toFixed(1)}°C → Новый теплоноситель=${newWaterTemp.toFixed(1)}°C`);

        // ---- Формируем сообщение для Telegram ----
        let roomLog = `🌡 Температура на улице: ${outsideTemp.toFixed(1)}°C\n`;
        roomLog += `📉 Прогноз через 6 часов: ${forecastTemp.toFixed(1)}°C\n`;
        roomLog += `💨 Скорость ветра: ${windSpeed.toFixed(1)} м/с\n`;
        roomLog += `🔆 УФ: ${uvIndex.toFixed(1)}, ${cloudEmoji} Облачность: ${cloudiness.toFixed(0)}%\n`;
        roomLog += `🌦️ Погода: ${weatherCondition}\n`;
        const boilerOn = isBoilerOn();
        const boilerEmoji = boilerOn ? "✅" : "❌";
        const floorPumpOn = isFloorPumpOn();
        const floorPumpEmoji = floorPumpOn ? "🔄" : "🚫";
        const presenceEmojis = getPresenceEmojis();
        roomLog += `🔥 Базовая температура теплоносителя: ${baseWaterTemp.toFixed(1)}°C ${boilerEmoji} ${floorPumpEmoji}${presenceEmojis ? " " + presenceEmojis : ""}\n\n`;

        // Данные по каждой комнате
        for (var room in rooms) {
            let currentTemp = rooms[room].sensor;
            let targetRoomTemp = rooms[room].target;
            let delta = targetRoomTemp - currentTemp;
            let deltaColor = delta > 0 ? "🔴" : "🔵";
            let status = "";
            let airQualityInfo = "";

            const windowOpen = isWindowOpen(room);
            const ventilationOn = isVentilationOn(room);
            const floorHeatingOn = isFloorHeatingOn(room);
            const radiatorOn = isRadiatorOn(room);

            if (radiatorOn) {
                status += " 💢"; // радиатор греет
            }
            if (floorHeatingOn) {
                status += " ♨️"; // тёплый пол включён
            }
            if (windowOpen) {
                status += " 🪟"; // открыто окно
            }
            if (ventilationOn) {
                status += " 🌀"; // включена вентиляция
            }

            // Качество воздуха показываем только когда окно/вентиляция активны (иначе не актуально)
            if (windowOpen || ventilationOn) {
                const airData = getAirQualityData(room);
                if (airData) {
                    airQualityInfo = ` ${airData.type} ${airData.value} ${airData.unit}`;
                }
            }

            roomLog += `🏠 ${room}: Сейчас ${currentTemp.toFixed(1)}°C, Цель ${targetRoomTemp}°C, ${deltaColor} ${delta.toFixed(1)}°C${status}${airQualityInfo}\n`;
        }

        // Блок коррекции отопления
        roomLog += `\n🔥 Коррекция отопления:\n`;
        roomLog += `Самая холодная комната:\n`;

        let ignoredRoomsList = Object.keys(rooms).filter(room => ignoreTemperature[room]);
        if (ignoredRoomsList.length > 0) {
            ignoredRoomsList.forEach(room => {
                let delta = rooms[room].target - rooms[room].sensor;
                roomLog += `🚫: ${delta.toFixed(1)}°C ${room} игнорируется\n`;
            });
        }

        if (coldestRoom) {
            let delta = rooms[coldestRoom].target - rooms[coldestRoom].sensor;
            let deltaColor = delta > 0 ? "🔴" : "🔵";
            roomLog += `${deltaColor} ${delta.toFixed(1)}°C ${coldestRoom}\n`;
        } else {
            roomLog += `🚫 Нет активных комнат для учёта.\n`;
        }

        roomLog += `Текущий теплоноситель: ${currentWaterTemp.toFixed(1)}°C\n`;

        if (newWaterTemp !== currentWaterTemp) {
            roomLog += `Новый теплоноситель: ${newWaterTemp.toFixed(1)}°C\n`;
        } else {
            roomLog += `⚖️ Изменение температуры теплоносителя не требуется.\n`;
        }

        // Теневой ПИ-тест — не управляет котлом, только для анализа/калибровки
        roomLog += `🧪 PI-тест (не управляет котлом): Δ=${rawMinDelta.toFixed(1)}°C, интеграл=${global.heatingIntegral.toFixed(2)}, рекомендация=${newWaterTemp_PI}°C\n`;

        sendTG(roomLog);

        // ---- Устанавливаем новую температуру теплоносителя на котле ----
        try {
            var acc = Hub.getAccessory(275);
            if (!acc) throw new Error("accessory=null");

            var svc = acc.getService(13);
            if (!svc) throw new Error("service=13 null");

            var ch = svc.getCharacteristic(18);
            if (!ch) throw new Error("char=18 null");

            ch.setValue(newWaterTemp);
        } catch (e) {
            log.error("⛔ Установка теплоносителя не выполнена: " + e.message);
        }

    } catch (e) {
        log.error("⛔ Ошибка в функции adjust_heating: " + e.message);
        sendTG("⚠️ Критическая ошибка. Проверьте логи системы.: " + e.message);
    }
};
